    STCEntry_Retail entries[2] = { { 3, 0 }, { 0x2d, (CTCBase_Retail*)&points } };
    bedThing.m_tcs.m_pFirst = entries; bedThing.m_tcs.m_pLast = entries + 2; bedThing.m_tcs.m_pEnd = entries + 2;
    bedThing.m_tcMask[0] = 0x55; bedThing.m_tcMask[1] = 1UL << 13;
    CScriptThing sleeper, bed; sleeper.m_thing = &sleeperThing; sleeper.m_valid = true; bed.m_thing = &bedThing; bed.m_valid = true;
    CGameScriptInterface gsi; gsi.World = 0;
    C3DVector pos, dir; pos.X = pos.Y = pos.Z = -1.0f; dir.X = dir.Y = dir.Z = -1.0f;
    int bad = 0;
    sleeper.m_valid = false;
    if (gsi.GetSleepingPositionAndOrientationFromBed(sleeper, bed, pos, dir) || pos.X != -1.0f) bad = 1;
    sleeper.m_valid = true; bed.m_valid = false;
    if (gsi.GetSleepingPositionAndOrientationFromBed(sleeper, bed, pos, dir)) bad = 2;
    bed.m_valid = true; bedThing.m_tcMask[0] = 0;
    if (gsi.GetSleepingPositionAndOrientationFromBed(sleeper, bed, pos, dir)) bad = 3;
    bedThing.m_tcMask[0] = 0x55; bedThing.m_tcMask[1] = 0;
    if (gsi.GetSleepingPositionAndOrientationFromBed(sleeper, bed, pos, dir)) bad = 4;
    bedThing.m_tcMask[1] = 1UL << 13; points.m_free = 0;
    if (gsi.GetSleepingPositionAndOrientationFromBed(sleeper, bed, pos, dir) || points.m_used != -1 || dir.X != -1.0f) bad = 5;
    points.m_free = 1;
    if (!gsi.GetSleepingPositionAndOrientationFromBed(sleeper, bed, pos, dir)) bad = 6;
    if (pos.X != 1.0f || pos.Z != 3.0f || dir.X != 4.0f || dir.Y != 5.0f || dir.Z != 6.0f || points.m_used != 7 || points.m_user != &sleeperThing) bad = 7;
